const BREACH_LINE_WIDTH = 16;const BREACH_LINE_COUNT = 18;const BREACH_WORD_COUNT = 8;const BREACH_BRACKET_COUNT = 6;const BREACH_MAX_ATTEMPTS = 5;const BREACH_LENGTH_RANGES ={short: [4, 5], medium: [6, 7], long: [8, 9]};const BREACH_JUNK_CHARS = "!@#$%^&*_+-=~<>?/\\|;:,.".split("");const BREACH_BRACKET_STYLES = [["[", "]"], ["(", ")"], ["<", ">"], ["{", "}"]];const BREACH_STATS_KEY = "gama_access_breach_stats";let breachGrid = [];let breachConsumedBrackets = new Set();let breachWordPlacements ={};let breachBracketPlacements = [];let breachTarget = "";let breachCandidates = []; let breachRejected = new Set();let breachAttemptsUsed = 0;let breachOver = false;let breachBusy = false; function scoreBreachGuess(target, guess){let matches = 0;for (let i = 0;i < target.length;i++){if (target[i] === guess[i]) matches++;}return matches;}function pickBreachWords(wordList, length, count, rng = Math.random){const candidates = wordList.filter((w) => w.length === length && /^[a-z]+$/.test(w));const pool = [...candidates];for (let i = pool.length - 1;i > 0;i--){const j = Math.floor(rng() * (i + 1));[pool[i], pool[j]] = [pool[j], pool[i]];}const picked = pool.slice(0, count);return{target: picked[0], decoys: picked.slice(1)};}function generateBreachGrid(lineWidth, lineCount, words, bracketCount, rng = Math.random){const grid = Array.from({length: lineCount}, () => Array(lineWidth).fill(null));const wordPlacements ={};const bracketPlacements = [];function tryPlace(length, maxAttempts){for (let attempt = 0;attempt < maxAttempts;attempt++){const line = Math.floor(rng() * lineCount);const maxStart = lineWidth - length;if (maxStart < 0) continue;const start = Math.floor(rng() * (maxStart + 1));let free = true;for (let i = 0;i < length;i++){if (grid[line][start + i] !== null){free = false;break;}}if (free) return{line, start};}return null;}for (const word of words){const pos = tryPlace(word.length, 200);if (!pos) continue;for (let i = 0;i < word.length;i++){grid[pos.line][pos.start + i] ={char: word[i], type: "word", word};}wordPlacements[word] = pos;}for (let b = 0;b < bracketCount;b++){const size = 3 + Math.floor(rng() * 3);const pos = tryPlace(size, 200);if (!pos) continue;const [open, close] = BREACH_BRACKET_STYLES[b % BREACH_BRACKET_STYLES.length];const id = `bracket-${b}`;grid[pos.line][pos.start] ={char: open, type: "bracket", id};grid[pos.line][pos.start + size - 1] ={char: close, type: "bracket", id};for (let i = 1;i < size - 1;i++){grid[pos.line][pos.start + i] ={char: BREACH_JUNK_CHARS[Math.floor(rng() * BREACH_JUNK_CHARS.length)], type: "bracket-fill", id};}bracketPlacements.push({id, line: pos.line, start: pos.start, size});}for (let l = 0;l < lineCount;l++){for (let c = 0;c < lineWidth;c++){if (grid[l][c] === null){grid[l][c] ={char: BREACH_JUNK_CHARS[Math.floor(rng() * BREACH_JUNK_CHARS.length)], type: "junk"};}}}return{grid, wordPlacements, bracketPlacements};} function loadBreachStats(){try{const raw = localStorage.getItem(BREACH_STATS_KEY);return raw ? JSON.parse(raw) :{solved: 0, lockouts: 0};}catch{return{solved: 0, lockouts: 0};}}function saveBreachStats(stats){try{localStorage.setItem(BREACH_STATS_KEY, JSON.stringify(stats));}catch{}}function renderBreachStats(){const stats = loadBreachStats();document.getElementById("breach-stats").textContent = `puzzles solved: ${stats.solved} // console lockouts: ${stats.lockouts}`;} function newBreachGame(){const difficulty = document.getElementById("breach-difficulty").value;const [min, max] = BREACH_LENGTH_RANGES[difficulty];const length = min + Math.floor(Math.random() * (max - min + 1));const{target, decoys}= pickBreachWords(WORD_LIST, length, BREACH_WORD_COUNT);const words = [target, ...decoys];const result = generateBreachGrid(BREACH_LINE_WIDTH, BREACH_LINE_COUNT, words, BREACH_BRACKET_COUNT);breachGrid = result.grid;breachWordPlacements = result.wordPlacements;breachBracketPlacements = result.bracketPlacements;breachTarget = target;breachCandidates = Object.keys(breachWordPlacements);breachRejected = new Set();breachConsumedBrackets = new Set();breachAttemptsUsed = 0;breachOver = false;breachBusy = false;document.getElementById("breach-log").innerHTML = "";document.getElementById("breach-result").textContent = "";renderBreachTerminal();renderBreachStats();GAMA.say("idle");}function breachAttemptsRemaining(){return BREACH_MAX_ATTEMPTS - breachAttemptsUsed;}function renderBreachTerminal(){const container = document.getElementById("breach-terminal");container.textContent = "";container.style.fontFamily = "var(--font-mono)";container.style.whiteSpace = "pre";container.style.lineHeight = "1.5";container.style.userSelect = "none";let hexAddr = 0xfac5;for (let l = 0;l < BREACH_LINE_COUNT;l++){const lineEl = document.createElement("div");const addr = document.createElement("span");addr.textContent = `0x${hexAddr.toString(16).toUpperCase()}  `;addr.style.color = "var(--phosphor-dim-text)";lineEl.appendChild(addr);hexAddr += 0x0a;for (let c = 0;c < BREACH_LINE_WIDTH;c++){const cellData = breachGrid[l][c];const span = document.createElement("span");span.textContent = cellData.char;if (cellData.type === "word"){const rejected = breachRejected.has(cellData.word);const isTarget = cellData.word === breachTarget;span.style.color = rejected ? "var(--phosphor-dim-text)" : "var(--phosphor)";span.style.textDecoration = rejected ? "line-through" : "none";if (!rejected && !breachOver){span.style.cursor = "pointer";span.dataset.breachWord = cellData.word;span.addEventListener("click", () => executeBreachGuess(cellData.word));} if (breachOver && isTarget){span.style.color = "var(--phosphor)";span.style.background = "rgba(57,255,20,0.25)";span.style.textDecoration = "none";}}else if (cellData.type === "bracket" || cellData.type === "bracket-fill"){const consumed = breachConsumedBrackets.has(cellData.id);span.style.color = consumed ? "var(--phosphor-dim-text)" : "var(--amber)";if (!consumed && !breachOver && !breachBusy){span.style.cursor = "pointer";span.addEventListener("click", () => executeBreachBracket(cellData.id));}}else{span.style.color = "var(--phosphor-dim-text)";}lineEl.appendChild(span);}container.appendChild(lineEl);}const meta = document.getElementById("breach-meta");meta.textContent = `attempts remaining: ${breachAttemptsRemaining()}/${BREACH_MAX_ATTEMPTS}`;} function executeBreachGuess(word){if (breachOver || breachBusy || breachRejected.has(word)) return;breachBusy = true;const result = document.getElementById("breach-result");result.textContent = "> please wait while system is accessed...";GAMA.say("working");setTimeout(() =>{breachBusy = false;const log = document.getElementById("breach-log");const entry = document.createElement("div");if (word === breachTarget){breachOver = true;entry.textContent = `${word.toUpperCase()} > access granted.`;result.textContent = "> ACCESS GRANTED";const stats = loadBreachStats();stats.solved++;saveBreachStats(stats);renderBreachStats();GAMA.say("success");}else{breachAttemptsUsed++;breachRejected.add(word);const matches = scoreBreachGuess(breachTarget, word);entry.textContent = `${word.toUpperCase()} > entry denied. ${matches}/${word.length} correct.`;if (breachAttemptsUsed >= BREACH_MAX_ATTEMPTS){breachOver = true;result.textContent = `> LOCKOUT. password was: ${breachTarget.toUpperCase()}`;const stats = loadBreachStats();stats.lockouts++;saveBreachStats(stats);renderBreachStats();GAMA.say("error");}else{result.textContent = `> ${matches}/${word.length} correct - ${breachAttemptsRemaining()} attempt${breachAttemptsRemaining() === 1 ? "" : "s"} left`;GAMA.say("idle");}}log.prepend(entry);renderBreachTerminal();}, 600);} function executeBreachBracket(id){if (breachOver || breachBusy || breachConsumedBrackets.has(id)) return;breachConsumedBrackets.add(id);const removableCandidates = breachCandidates.filter((w) => w !== breachTarget && !breachRejected.has(w));const canRestore = breachAttemptsUsed > 0;let wantRemove = Math.random() < 0.5;if (wantRemove && removableCandidates.length === 0) wantRemove = false;if (!wantRemove && !canRestore) wantRemove = removableCandidates.length > 0;const result = document.getElementById("breach-result");if (wantRemove){const removed = removableCandidates[Math.floor(Math.random() * removableCandidates.length)];breachRejected.add(removed);result.textContent = `> dud triggered: ${removed.toUpperCase()} purged from candidate list`;}else if (canRestore){breachAttemptsUsed--;result.textContent = "> dud triggered: attempt restored";}else{result.textContent = "> dud triggered: no effect this time";}renderBreachTerminal();} function breachIsTypingElsewhere(){const el = document.activeElement;if (!el) return false;return el.tagName === "INPUT" || el.tagName === "TEXTAREA" || el.tagName === "SELECT" || el.isContentEditable;}document.addEventListener("keydown", (e) =>{if (e.key !== "Escape" || !document.getElementById("breach-terminal") || breachIsTypingElsewhere()) return;if (breachOver || breachBusy) return;breachOver = true;const stats = loadBreachStats();stats.lockouts++;saveBreachStats(stats);document.getElementById("breach-result").textContent = `> connection aborted (counts as a lockout). password was: ${breachTarget.toUpperCase()}`;renderBreachStats();renderBreachTerminal();GAMA.say("error");e.preventDefault();});document.addEventListener("DOMContentLoaded", () =>{if (document.getElementById("breach-terminal")) newBreachGame();});